//! Gate-inert payload records; protected simulator remains unchanged.
use crate::circuit::{Op,QubitId,analyze_ops};
use alloy_primitives::U256;
use sha3::{Shake256,digest::{Update,ExtendableOutput}};
use std::sync::Mutex;
#[derive(Clone)]struct Mark{at:usize,id:usize,before:bool,phase:&'static str,t:usize,rev:bool,pay:[Vec<QubitId>;2],letter:Vec<QubitId>}
static MARKS:Mutex<Vec<Mark>>=Mutex::new(Vec::new());
pub fn begin(at:usize,phase:&'static str,t:usize,rev:bool,pay:&[Vec<QubitId>;2],letter:&[QubitId])->usize{let mut m=MARKS.lock().unwrap();let id=m.len();m.push(Mark{at,id,before:true,phase,t,rev,pay:pay.clone(),letter:letter.to_vec()});id}
pub fn end(id:usize,at:usize,pay:&[Vec<QubitId>;2],letter:&[QubitId]){let mut ms=MARKS.lock().unwrap();let mut m=ms.iter().find(|m|m.id==id&&m.before).unwrap().clone();m.at=at;m.before=false;m.pay=pay.clone();m.letter=letter.to_vec();ms.push(m);}
fn word(q:&[QubitId],w:&[u64],lane:usize)->U256{assert_eq!(q.len(),256);let mut v=U256::ZERO;for(i,q)in q.iter().enumerate(){if(w[q.0 as usize]>>lane)&1!=0{v|=U256::from(1)<<i;}}v}
pub fn run(ops:&[Op]){let root="/home/hclau/ecdsa_research/payload-model-20261016";let(nq,nb,_,regs)=analyze_ops(ops.iter());let marks=MARKS.lock().unwrap().clone();assert!(marks.windows(2).all(|x|x[0].at<=x[1].at));let txt=std::fs::read_to_string(format!("{root}/packets/audit.tsv")).unwrap();let rows:Vec<[U256;6]>=txt.lines().map(|l|l.split_whitespace().skip(1).map(|v|U256::from_str_radix(v.trim_start_matches("0x"),16).unwrap()).collect::<Vec<_>>().try_into().unwrap()).collect();
for(batch,rows)in rows.chunks(64).enumerate(){let mut h=Shake256::default();h.update(b"payload-model-20261016");h.update(&(batch as u64).to_le_bytes());let mut rng=h.finalize_xof();let mut rr=rng.clone();let mut s=super::observed_sim::Simulator::new(nq as usize,nb as usize,&mut rng);let mut r=crate::sim::Simulator::new(nq as usize,nb as usize,&mut rr);for(lane,v)in rows.iter().enumerate(){for k in 0..4{s.set_register(&regs[k],v[k],lane);r.set_register(&regs[k],v[k],lane);}}
let mut cursor=0;s.apply_observed(ops.iter(),|idx,s,_,_|{while cursor<marks.len()&&marks[cursor].at==idx{let m=&marks[cursor];cursor+=1;for lane in 0..rows.len(){let tape:Vec<u64>=m.letter.iter().map(|q|(s.qubits[q.0 as usize]>>lane)&1).collect();eprintln!("PAYLOAD_OBS shot={} id={} before={} phase={} tick={} rev={} at={} p0={:#x} p1={:#x} tape={tape:?}",batch*64+lane,m.id,m.before,m.phase,m.t,m.rev,m.at,word(&m.pay[0],&s.qubits,lane),word(&m.pay[1],&s.qubits,lane));}}});assert_eq!(cursor,marks.len());r.apply_iter(ops.iter());assert_eq!(s.qubits,r.qubits);assert_eq!(s.bits,r.bits);assert_eq!(s.phase,r.phase);assert_eq!(s.stats.toffoli_gates,r.stats.toffoli_gates);for(lane,v)in rows.iter().enumerate(){eprintln!("PAYLOAD_FINAL shot={} correct={} phase={:#x} all_state_equal=true",batch*64+lane,s.get_register(&regs[0],lane)==v[4]&&s.get_register(&regs[1],lane)==v[5],s.phase);}eprintln!("PAYLOAD_PROTECTED_EQUAL shots={} qubits={nq} bits={nb} phase=true toffolis=true score=NONE",rows.len());}}
